const assertServiceId = (value) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new Error(`Invalid service_id: ${value}`);
  }
  return text;
};

const item = $input.first();
const body = item.json.body ?? item.json ?? {};

const serviceId = assertServiceId(body.service_id);

// El archivo llega en la propiedad binaria `data` (el front hace
// formData.append('data', file), igual que el logo de clínica y la firma).
const binary = item.binary?.data;
if (!binary) throw new Error('image file is required (binary property "data")');

const allowed = ['image/png', 'image/jpeg', 'image/webp'];
if (!allowed.includes(binary.mimeType)) {
  throw new Error(`Unsupported image type: ${binary.mimeType}`);
}

// 1 MB, el mismo límite que valida el front.
if (binary.fileSize && Number(String(binary.fileSize).replace(/[^0-9]/g, '')) > 1024 * 1024) {
  throw new Error('Image file exceeds 1 MB');
}

const extension = binary.mimeType === 'image/webp' ? 'webp'
  : binary.mimeType === 'image/jpeg' ? 'jpg' : 'png';

return [{
  json: {
    service_id: serviceId,
    filename: binary.fileName || `service-${serviceId}.${extension}`,
    mimetype: binary.mimeType,
  },
  binary: item.binary,
}];

// El borrado del archivo anterior es best-effort: si falla, la imagen nueva ya
// quedó guardada y no hay razón para devolver un error al usuario.
const saved = $('Guardar en service_catalog').first().json;

if (!saved || saved.error || !saved.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la imagen.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  service_id: saved.id,
  filename: saved.image_filename,
  mimetype: saved.image_mimetype,
  image_updated_at: saved.image_updated_at,
} } }];
